from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def analyze(I,O):
    cnt=Counter(x for row in I for x in row if x!=0)
    mark=min(cnt,key=lambda k:cnt[k])
    h,w=len(I),len(I[0])
    shp=[(r,c) for r in range(h) for c in range(w) if I[r][c]==mark]
    added={(r,c) for r in range(h) for c in range(w) if O[r][c]==mark and I[r][c]!=mark}
    # all translations fully in grid (no zero restriction); union of cells
    un=set(); res=[]
    for dr in range(-h+1,h):
        for dc in range(-w+1,w):
            if all(0<=r+dr<h and 0<=c+dc<w for r,c in shp):
                un.update((r+dr,c+dc) for r,c in shp)
    res.append(('all-in-grid', un==added))
    # translations whose cells all lie on zeros
    zun=set()
    for dr in range(-h+1,h):
        for dc in range(-w+1,w):
            if all(0<=r+dr<h and 0<=c+dc<w and I[r+dr][c+dc]==0 for r,c in shp):
                zun.update((r+dr,c+dc) for r,c in shp)
    res.append(('on-zeros', zun==added))
    return mark,shp,added,res
